insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"noun_repair_q01_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q01_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q02_finish","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q02_start","speaker_external_id":"Little Boy","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q03_finish","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q03_start","speaker_external_id":"Farmer","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q04_finish","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q04_start","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q05_finish","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q05_start","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q06_finish","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}},{"key":"noun_repair_q06_start","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\noun_repair_shop.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":0,"content":"יש! ה־book שוב הוא book, וה־table שוב עומד על ארבע רגליים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":1,"content":"קחו את ה־Gem ל־Little Boy. הוא מצא שק של חפצים עם שמות שבורים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":2,"content":"תודה, noun-repair hero! בלי עזרה, הייתי קוראת לעצמי toaster.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":0,"content":"אוי לא! ספר התיקון התפרק, ושמות החפצים נעלמו מהתוויות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":1,"content":"חפשו את המילים החסרות, השלימו אותיות ובנו משפט קצר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":2,"content":"אחרי שתסיימו, הביאו לי Gem. אחר כך אשלח אתכם ל־Little Boy.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":0,"content":"מצאתם הכול! ה־dog הפסיק לנבוח על ה־pencil. זה הישג גדול.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":1,"content":"קחו את ה־Power Stone ל־Farmer. בשוק שלו apple ו־bread החליפו תוויות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":2,"content":"תודה! עכשיו ה־bag שלי מכיל חפצים, לא שמות של חיות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":0,"content":"השק שלי ברח והשאיר אחריו תוויות שבורות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":1,"content":"תקנו שמות של חפצים וחיות, ובנו משפט קצר באנגלית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":2,"content":"מצאו את השמות, קבלו Power Stone וחזרו אליי. אז נלך ל־Farmer בשוק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":0,"content":"השוק ניצל! עכשיו כולם יודעים ש־apple הוא פרי ו־bread הוא אוכל.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":1,"content":"קחו את ה־Ancient Rune ל־Old Woman. במטבח שלה ה־spoon כנראה מנהל את הטבח.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":2,"content":"תודה! היום אף אחד לא יקנה hammer ויגלה בבית banana.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":0,"content":"ברוכים הבאים לשוק! התוויות התבלבלו, והלקוחות כבר לא יודעים מה הם קונים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":1,"content":"תקנו שמות של פירות, אוכל וכלי עבודה. בבקשה אל תאכלו את השלטים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":2,"content":"אחרי שתצליחו, קבלו Ancient Rune וחזרו אליי. Old Woman מחכה במטבח.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":0,"content":"ה־spoon חזר לערבב, ה־chef חזר לבשל, וה־plate הפסיק לתת פקודות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":1,"content":"קחו את ה־Gem ל־Professor Crazy. הוא מצא את התוויות של הארמון.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":2,"content":"תודה! הכנתי עוגה. אני מקווה שהמילה cake לא תתחפש ל־castle.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":0,"content":"במטבח התוויות התחלפו, ועכשיו אף אחד לא יודע מי עושה מה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":1,"content":"תקנו את שמות הכלים והאנשים. היזהרו: קסם מוזר מסתובב במטבח.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":2,"content":"קבלו Gem, חזרו אליי, ואז לכו ל־Professor Crazy בארמון.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":0,"content":"מושלם! ה־queen יושבת על ה־throne, וה־crown שוב על הראש ולא על האף.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":1,"content":"קחו את ה־Power Stone ל־Maya. נשאר רק מבחן noun אחד.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":2,"content":"תודה! המדע מודה לכם. אני מודה לכם. ה־crown עדיין לא מודה לאף אחד.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":0,"content":"הניסוי הצליח! כלומר, הוא נכשל בצורה מצחיקה, וכל תוויות הארמון התחלפו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":1,"content":"תקנו את שמות המקומות, תפקידי הארמון והחפצים המלכותיים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":2,"content":"אחרי Power Stone אחד, חזרו אליי. אשלח אתכם למבחן הסיום אצל Maya.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":0,"content":"וואו! תיקנתם את כל השמות. אתם יודעים לזהות noun, לאיית אותו ולקרוא אותו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":1,"content":"הספר נפתח, ה־cat קיבל שם, וה־table הפסיק לדרוש כתר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":2,"content":"תודה רבה! Noun Repair Shop פתוח. קחו את הפרס — והיזהרו מה־toaster.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":0,"content":"חזרתם! כל חלקי הספר כאן. עכשיו נראה אם אתם באמת מכירים שמות עצם ולא רק מתקנים אותם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":1,"content":"תעברו מבחן קצר על אנשים, חפצים, מקומות וחיות. קראו כל מילה באנגלית בקול.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":2,"content":"אם תצליחו, תחזירו לי את ה־Ancient Rune ונפתח מחדש את הסדנה.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
